    // Cart Counter Logic
    let cartCount = 0;
    const cartCountElement = document.querySelector('.cart-count');
    const addToCartButtons = document.querySelectorAll('.add-to-cart');

    addToCartButtons.forEach(button => {
        button.addEventListener('click', () => {
            cartCount++;
            cartCountElement.textContent = cartCount;

            // Basic feedback
            const productName = button.getAttribute('data-product');
            showNotification(`Added ${productName} to cart!`);

            // Accessibility: Announce to screen readers
            announceToScreenReader(`${productName} added to cart. Current items: ${cartCount}`);
        });
    });

    // Newsletter Form Logic
    const newsletterForm = document.getElementById('newsletter-form');
    if (newsletterForm) {
        newsletterForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const email = newsletterForm.querySelector('input').value;
            showNotification(`Thanks for subscribing with ${email}!`);
            newsletterForm.reset();
        });
    }

    // Simple Notification System
    function showNotification(message) {
        const notification = document.createElement('div');
        notification.className = 'toast-notification';
        notification.textContent = message;

        // Style notification (could also be in CSS)
        Object.assign(notification.style, {
            position: 'fixed',
            bottom: '2rem',
            right: '2rem',
            backgroundColor: '#d4af37',
            color: '#0a0a0a',
            padding: '1rem 2rem',
            borderRadius: '4px',
            fontWeight: 'bold',
            boxShadow: '0 4px 12px rgba(0,0,0,0.5)',
            zIndex: '2000',
            transition: 'opacity 0.3s ease'
        });

        document.body.appendChild(notification);

        setTimeout(() => {
            notification.style.opacity = '0';
            setTimeout(() => notification.remove(), 300);
        }, 3000);
    }

    // Accessibility Helper: Live Region for Screen Readers
    function announceToScreenReader(message) {
        let announcement = document.getElementById('sr-announcer');
        if (!announcement) {
            announcement = document.createElement('div');
            announcement.id = 'sr-announcer';
            announcement.setAttribute('aria-live', 'polite');
            announcement.className = 'sr-only';
            document.body.appendChild(announcement);
        }
        announcement.textContent = message;
    }

    // Header scroll effect
    window.addEventListener('scroll', () => {
        const header = document.querySelector('.site-header');
        if (window.scrollY > 50) {
            header.style.padding = '0.5rem 0';
            header.style.boxShadow = '0 4px 20px rgba(0,0,0,0.4)';
        } else {
            header.style.padding = '1rem 0';
            header.style.boxShadow = 'none';
        }
    });
});
