    --bg-color: #0a0a0a;
    --surface-color: #1a1a1a;
    --text-primary: #ffffff;
    --text-secondary: #a0a0a0;
    --accent-color: #d4af37; /* Gold accent */
    --accent-hover: #f1c40f;
    --border-color: #333333;
    --font-main: 'Inter', system-ui, -apple-system, sans-serif;
    --container-width: 1200px;
    --transition: all 0.3s ease;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    background-color: var(--bg-color);
    color: var(--text-primary);
    font-family: var(--font-main);
    line-height: 1.6;
}

.container {
    max-width: var(--container-width);
    margin: 0 auto;
    padding: 0 2rem;
}

/* Header */
.site-header {
    background-color: rgba(10, 10, 10, 0.95);
    backdrop-filter: blur(10px);
    position: sticky;
    top: 0;
    z-index: 1000;
    border-bottom: 1px solid var(--border-color);
    padding: 1rem 0;
}

.site-header .container {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-size: 1.8rem;
    font-weight: 800;
    color: var(--text-primary);
    text-decoration: none;
    letter-spacing: 2px;
}

.main-nav ul {
    display: flex;
    list-style: none;
    gap: 2rem;
}

.main-nav a {
    color: var(--text-primary);
    text-decoration: none;
    font-weight: 500;
    text-transform: uppercase;
    font-size: 0.9rem;
    letter-spacing: 1px;
    transition: var(--transition);
}

.main-nav a:hover {
    color: var(--accent-color);
}

.header-actions {
    display: flex;
    gap: 1.5rem;
}

.header-actions button {
    background: none;
    border: none;
    color: var(--text-primary);
    cursor: pointer;
    font-size: 1.2rem;
    position: relative;
    transition: var(--transition);
}

.header-actions button:hover {
    color: var(--accent-color);
}

.cart-count {
    position: absolute;
    top: -8px;
    right: -10px;
    background-color: var(--accent-color);
    color: var(--bg-color);
    font-size: 0.7rem;
    font-weight: bold;
    padding: 2px 6px;
    border-radius: 50%;
}

/* Hero Section */
.hero {
    height: 80vh;
    display: flex;
    align-items: center;
    background: linear-gradient(rgba(0,0,0,0.6), rgba(0,0,0,0.6)), url('https://images.unsplash.com/photo-1441984904996-e0b6ba687e04?q=80&w=1200&auto=format&fit=crop');
    background-size: cover;
    background-position: center;
    text-align: center;
}

.hero-content h1 {
    font-size: 4rem;
    margin-bottom: 1rem;
    letter-spacing: -1px;
}

.hero-content p {
    font-size: 1.2rem;
    color: var(--text-secondary);
    max-width: 600px;
    margin: 0 auto 2rem;
}

.cta-button {
    display: inline-block;
    background-color: var(--accent-color);
    color: var(--bg-color);
    padding: 1rem 2.5rem;
    text-decoration: none;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
    border-radius: 4px;
    transition: var(--transition);
}

.cta-button:hover {
    background-color: var(--accent-hover);
    transform: translateY(-2px);
}

/* Featured Products */
.featured-products {
    padding: 5rem 0;
}

.featured-products h2 {
    text-align: center;
    margin-bottom: 3rem;
    font-size: 2.5rem;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2.5rem;
}

.product-card {
    background-color: var(--surface-color);
    border-radius: 8px;
    overflow: hidden;
    transition: var(--transition);
    border: 1px solid var(--border-color);
}

.product-card:hover {
    transform: translateY(-5px);
    border-color: var(--accent-color);
}

.product-image img {
    width: 100%;
    height: 350px;
    object-fit: cover;
    display: block;
}

.product-info {
    padding: 1.5rem;
    text-align: center;
}

.product-info h3 {
    margin-bottom: 0.5rem;
    font-size: 1.25rem;
}

.price {
    color: var(--accent-color);
    font-weight: 700;
    font-size: 1.1rem;
    margin-bottom: 1.5rem;
}

.add-to-cart {
    width: 100%;
    padding: 0.8rem;
    background: none;
    border: 1px solid var(--accent-color);
    color: var(--accent-color);
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition);
    border-radius: 4px;
}

.add-to-cart:hover {
    background-color: var(--accent-color);
    color: var(--bg-color);
}

/* Deals Section */
.deals-section {
    padding: 5rem 0;
    background-color: #000;
}

.deals-banner {
    background: linear-gradient(45deg, #1a1a1a, #333);
    padding: 4rem;
    border-radius: 12px;
    text-align: center;
    border: 1px solid var(--accent-color);
}

.deals-content h3 {
    font-size: 3rem;
    margin-bottom: 1rem;
    color: var(--accent-color);
}

.deals-content p {
    font-size: 1.2rem;
    margin-bottom: 2rem;
    color: var(--text-secondary);
}

.secondary-button {
    display: inline-block;
    padding: 0.8rem 2rem;
    border: 2px solid var(--text-primary);
    color: var(--text-primary);
    text-decoration: none;
    font-weight: 600;
    transition: var(--transition);
}

.secondary-button:hover {
    background-color: var(--text-primary);
    color: var(--bg-color);
}

/* Editorial Section */
.editorial-section {
    padding: 5rem 0;
}

.editorial-section h2 {
    text-align: center;
    margin-bottom: 3rem;
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
    gap: 3rem;
}

.editorial-card {
    position: relative;
    overflow: hidden;
    border-radius: 8px;
}

.editorial-card img {
    width: 100%;
    height: 500px;
    object-fit: cover;
    display: block;
    transition: var(--transition);
}

.editorial-card:hover img {
    transform: scale(1.05);
}

.editorial-info {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    padding: 2rem;
    background: linear-gradient(transparent, rgba(0,0,0,0.9));
}

.editorial-info h3 {
    margin-bottom: 0.5rem;
}

.editorial-info p {
    color: var(--text-secondary);
    margin-bottom: 1rem;
}

.read-more {
    color: var(--accent-color);
    text-decoration: none;
    font-weight: 600;
}

/* Footer */
.site-footer {
    background-color: var(--surface-color);
    padding: 5rem 0 2rem;
    border-top: 1px solid var(--border-color);
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-grid h4 {
    margin-bottom: 1.5rem;
    color: var(--accent-color);
    text-transform: uppercase;
    letter-spacing: 1px;
}

.footer-links ul {
    list-style: none;
}

.footer-links li {
    margin-bottom: 0.8rem;
}

.footer-links a {
    color: var(--text-secondary);
    text-decoration: none;
    transition: var(--transition);
}

.footer-links a:hover {
    color: var(--text-primary);
}

#newsletter-form {
    display: flex;
    gap: 0.5rem;
}

#newsletter-form input {
    flex: 1;
    padding: 0.8rem;
    background-color: var(--bg-color);
    border: 1px solid var(--border-color);
    color: var(--text-primary);
    border-radius: 4px;
}

#newsletter-form button {
    padding: 0.8rem 1.5rem;
    background-color: var(--accent-color);
    color: var(--bg-color);
    border: none;
    border-radius: 4px;
    font-weight: 700;
    cursor: pointer;
}

.footer-bottom {
    text-align: center;
    border-top: 1px solid var(--border-color);
    padding-top: 2rem;
    color: var(--text-secondary);
    font-size: 0.9rem;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--accent-color);
    color: var(--bg-color);
    padding: 8px;
    z-index: 2000;
    transition: top 0.3s;
}

.skip-link:focus {
    top: 0;
}

/* Accessibility: Focus states */
a:focus, button:focus, input:focus {
    outline: 2px solid var(--accent-color);
    outline-offset: 4px;
}

@media (max-width: 768px) {
    .hero-content h1 {
        font-size: 2.5rem;
    }
    .main-nav {
        display: none; /* In a real app, I'd add a hamburger menu */
    }
    .editorial-grid {
        grid-template-columns: 1fr;
    }
}
