    border: 1px solid var(--accent-color);
}

.deals-content h3 {
    font-size: 3rem;
    margin-bottom: 1rem;
    color: var(--accent-color);
}

.deals-content p {
    font-size: 1.2rem;
    margin-bottom: 2rem;
    color: var(--text-secondary);
}

.secondary-button {
    display: inline-block;
    padding: 0.8rem 2rem;
    border: 2px solid var(--text-primary);
    color: var(--text-primary);
    text-decoration: none;
    font-weight: 600;
    transition: var(--transition);
}

.secondary-button:hover {
    background-color: var(--text-primary);
    color: var(--bg-color);
}

/* Editorial Section */
.editorial-section {
    padding: 5rem 0;
}

.editorial-section h2 {
    text-align: center;
    margin-bottom: 3rem;
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
    gap: 3rem;
}

.editorial-card {
    position: relative;
    overflow: hidden;
    border-radius: 8px;
}

.editorial-card img {
    width: 100%;
    height: 500px;
    object-fit: cover;
    display: block;
    transition: var(--transition);
}

.editorial-card:hover img {
    transform: scale(1.05);
}

.editorial-info {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    padding: 2rem;
    background: linear-gradient(transparent, rgba(0,0,0,0.9));
}

.editorial-info h3 {
    margin-bottom: 0.5rem;
}

.editorial-info p {
    color: var(--text-secondary);
    margin-bottom: 1rem;
}

.read-more {
    color: var(--accent-color);
    text-decoration: none;
    font-weight: 600;
}

/* Footer */
.site-footer {
    background-color: var(--surface-color);
    padding: 5rem 0 2rem;
    border-top: 1px solid var(--border-color);
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-grid h4 {
    margin-bottom: 1.5rem;
    color: var(--accent-color);
    text-transform: uppercase;
    letter-spacing: 1px;
}

.footer-links ul {
    list-style: none;
}

.footer-links li {
    margin-bottom: 0.8rem;
}

.footer-links a {
    color: var(--text-secondary);
    text-decoration: none;
    transition: var(--transition);
}

.footer-links a:hover {
    color: var(--text-primary);
}

#newsletter-form {
    display: flex;
    gap: 0.5rem;
}

#newsletter-form input {
    flex: 1;
    padding: 0.8rem;
    background-color: var(--bg-color);
    border: 1px solid var(--border-color);
    color: var(--text-primary);
    border-radius: 4px;
}

#newsletter-form button {
    padding: 0.8rem 1.5rem;
    background-color: var(--accent-color);
    color: var(--bg-color);
    border: none;
    border-radius: 4px;
    font-weight: 700;
    cursor: pointer;
}

.footer-bottom {
    text-align: center;
    border-top: 1px solid var(--border-color);
    padding-top: 2rem;
    color: var(--text-secondary);
    font-size: 0.9rem;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--accent-color);
    color: var(--bg-color);
    padding: 8px;
    z-index: 2000;
    transition: top 0.3s;
}

.skip-link:focus {
    top: 0;
}

/* Accessibility: Focus states */
a:focus, button:focus, input:focus {
    outline: 2px solid var(--accent-color);
    outline-offset: 4px;
}

@media (max-width: 768px) {
    .hero-content h1 {
        font-size: 2.5rem;
    }
    .main-nav {
        display: none; /* In a real app, I'd add a hamburger menu */
    }
    .editorial-grid {
        grid-template-columns: 1fr;
    }
}
